package store

import (
	"fmt"
	"sort"
	"time"
)

// AuditActor is who made a change: an API key, and the member the key acts for.
type AuditActor struct {
	Type   string `json:"type"` // "api_key"
	ID     string `json:"id"`
	UserID string `json:"user_id"`
}

// AuditTarget is the object a change was made to. For a member, the ID is the member's user ID.
type AuditTarget struct {
	Type string `json:"type"`
	ID   string `json:"id"`
}

// AuditChange is one field's value before and after an update.
type AuditChange struct {
	From any `json:"from"`
	To   any `json:"to"`
}

// AuditEntry records a successful change to an organization. Entries are never changed or removed.
type AuditEntry struct {
	ID        string      `json:"id"`
	OrgID     string      `json:"org_id"`
	Action    string      `json:"action"`
	Actor     AuditActor  `json:"actor"`
	Target    AuditTarget `json:"target"`
	RequestID string      `json:"request_id"`
	At        time.Time   `json:"at"`
	// Changes is set for updates, with one entry for each field whose value changed. It is nil for other actions.
	Changes *map[string]AuditChange `json:"changes,omitempty"`
}

// AuditFilter selects audit entries. An empty field matches everything.
type AuditFilter struct {
	Action   string
	TargetID string
	// ActorID is an API key ID or a user ID.
	ActorID string
}

// RecordAudit appends an entry to the audit log. The store gives it its ID and sets its time to now.
func (s *Store) RecordAudit(e AuditEntry, now time.Time) AuditEntry {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.auditSeq++
	e.ID = fmt.Sprintf("aud_%06d", s.auditSeq)
	e.At = now.UTC()
	s.audit = append(s.audit, e)
	return e
}

// AuditEntries returns an organization's audit entries that match f, oldest first.
func (s *Store) AuditEntries(orgID string, f AuditFilter) []AuditEntry {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []AuditEntry{}
	for _, e := range s.audit {
		if e.OrgID != orgID {
			continue
		}
		if f.Action != "" && e.Action != f.Action {
			continue
		}
		if f.TargetID != "" && e.Target.ID != f.TargetID {
			continue
		}
		if f.ActorID != "" && e.Actor.ID != f.ActorID && e.Actor.UserID != f.ActorID {
			continue
		}
		out = append(out, e)
	}
	sort.SliceStable(out, func(i, j int) bool {
		if !out[i].At.Equal(out[j].At) {
			return out[i].At.Before(out[j].At)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

