package api

import (
	"encoding/json"
	"net/http"
	"reflect"
	"slices"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

// audit records an entry for a request that succeeded. Call it before answering, so that the entry exists when the caller
// has the answer. changes is nil for actions that are not updates; an update passes changesOf, which is never nil.
func (s *Server) audit(r *http.Request, p auth.Principal, action, targetType, targetID string, changes map[string]store.AuditChange) {
	e := store.AuditEntry{
		OrgID:     p.OrgID,
		Action:    action,
		Actor:     store.AuditActor{Type: "api_key", ID: p.KeyID, UserID: p.UserID},
		Target:    store.AuditTarget{Type: targetType, ID: targetID},
		RequestID: RequestID(r.Context()),
	}
	if changes != nil {
		e.Changes = &changes
	}
	s.store.RecordAudit(e, s.clock.Now())
}

// changesOf returns the fields whose JSON value differs between before and after, leaving out the skipped fields. It is
// never nil: an update has a changes field even when nothing changed.
func changesOf(before, after any, skip ...string) map[string]store.AuditChange {
	from, to := jsonFields(before), jsonFields(after)
	names := map[string]bool{}
	for name := range from {
		names[name] = true
	}
	for name := range to {
		names[name] = true
	}
	changes := map[string]store.AuditChange{}
	for name := range names {
		if slices.Contains(skip, name) || reflect.DeepEqual(from[name], to[name]) {
			continue
		}
		changes[name] = store.AuditChange{From: from[name], To: to[name]}
	}
	return changes
}

// jsonFields returns the fields of v as the API shows them.
func jsonFields(v any) map[string]any {
	b, _ := json.Marshal(v) // every object that is audited marshals
	var fields map[string]any
	_ = json.Unmarshal(b, &fields)
	return fields
}

// auditView is an audit entry as the API shows it.
