	r := e.DoWith(method, path, key, body, http.Header{"X-Request-Id": {id}})
	if r.Code != code {
		t.Fatalf("%s %s: want %d, got %s", method, path, code, r)
	}
	if out != nil {
		r.JSON(t, out)
	}
}

// actorOf is the audit actor of the API key token: the key and the member it acts for.
func actorOf(t *testing.T, e *apitest.Env, token string) store.AuditActor {
	t.Helper()
	k, ok := e.Store.APIKeyByToken(token)
	if !ok {
		t.Fatal("no such API key")
	}
	return store.AuditActor{Type: "api_key", ID: k.ID, UserID: k.UserID}
}

// changed returns the fields an update changed, and fails when the entry has no changes field.
func changed(t *testing.T, ev auditEvent) map[string]store.AuditChange {
	t.Helper()
	if ev.Changes == nil {
		t.Fatalf("%s has no changes field", ev.Action)
	}
	return *ev.Changes
}

func TestAuditLogRecordsChanges(t *testing.T) {
	e := apitest.New(t)
	owner := actorOf(t, e, e.Acme.Key)
	var c store.Customer
	call(t, e, http.StatusCreated, "req-create", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane Doe", "email": "jane@example.com"}, &c)
	call(t, e, http.StatusOK, "req-rename", "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	call(t, e, http.StatusOK, "req-same", "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	call(t, e, http.StatusNoContent, "req-delete", "DELETE", "/v1/customers/"+c.ID, e.Acme.Key, nil, nil)

	var log []auditEvent
	for i := len(auditLog(t, e, e.Acme.Key, "")) - 1; i >= 0; i-- {
		log = append(log, auditLog(t, e, e.Acme.Key, "")[i])
	}
	want := []struct{ action, reqID string }{
		{"customer.created", "req-create"}, {"customer.updated", "req-rename"}, {"customer.updated", "req-same"}, {"customer.deleted", "req-delete"},
	}
	if len(log) != len(want) {
		t.Fatalf("%d entries, want %d: %+v", len(log), len(want), log)
	}
	for i, ev := range log {
		if ev.Action != want[i].action || ev.RequestID != want[i].reqID || ev.Actor != owner || ev.Target != (store.AuditTarget{Type: "customer", ID: c.ID}) {
			t.Fatalf("entry %d = %+v", i, ev)
		}
		if !ev.At.Equal(e.Clock.Now()) || !strings.HasPrefix(ev.ID, "aud_") {
			t.Fatalf("entry %d has time %v and id %q", i, ev.At, ev.ID)
		}
	}
	if got := changed(t, log[1]); len(got) != 1 || got["name"].From != "Jane Doe" || got["name"].To != "Jane Roe" {
		t.Fatalf("rename changed %+v", got)
	}
	if got := changed(t, log[2]); len(got) != 0 {
		t.Fatalf("a request that changed nothing changed %+v", got)
	}
	if log[0].Changes != nil || log[3].Changes != nil {
		t.Fatal("a create or a delete has a changes field")
	}
}

func TestAuditLogCoversEveryAction(t *testing.T) {
	e := apitest.New(t)
	var plan store.Plan
	call(t, e, http.StatusCreated, "p1", "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Team", "currency": "USD", "price": "20.00", "interval": "month"}, &plan)
	call(t, e, http.StatusOK, "p2", "PATCH", "/v1/plans/"+plan.ID, e.Acme.Key, map[string]any{"name": "Team Plus"}, nil)

	var jane, temp store.Customer
	call(t, e, http.StatusCreated, "c1", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane", "email": "jane@example.com"}, &jane)
	call(t, e, http.StatusOK, "c2", "PATCH", "/v1/customers/"+jane.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	call(t, e, http.StatusCreated, "c3", "POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Temp", "email": "temp@example.com"}, &temp)
	call(t, e, http.StatusNoContent, "c4", "DELETE", "/v1/customers/"+temp.ID, e.Acme.Key, nil, nil)

	var sub store.Subscription
	call(t, e, http.StatusCreated, "s1", "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": jane.ID, "plan_id": plan.ID, "quantity": 2}, &sub)
	call(t, e, http.StatusOK, "s2", "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"quantity": 3}, nil)
	call(t, e, http.StatusOK, "s3", "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, map[string]any{"at_period_end": true}, nil)

	var inv, paid store.Invoice
	lines := []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 500}}
	call(t, e, http.StatusCreated, "i1", "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": lines}, &inv)
	call(t, e, http.StatusOK, "i2", "POST", "/v1/invoices/"+inv.ID+"/void", e.Acme.Key, nil, nil)
	call(t, e, http.StatusCreated, "i3", "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": jane.ID, "currency": "USD", "lines": lines}, &paid)
	call(t, e, http.StatusOK, "i4", "POST", "/v1/invoices/"+paid.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}, nil)

	var key store.APIKey
	call(t, e, http.StatusCreated, "k1", "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &key)
	call(t, e, http.StatusNoContent, "k2", "DELETE", "/v1/api-keys/"+key.ID, e.Acme.Key, nil, nil)

	var inv2 store.Invite
	call(t, e, http.StatusCreated, "v1", "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@acme.example", "role": "member"}, &inv2)
	call(t, e, http.StatusNoContent, "v2", "DELETE", "/v1/invites/"+inv2.ID, e.Acme.Key, nil, nil)

	bob, _ := e.AddMember(e.Acme, "bob@acme.example", store.RoleMember)
	call(t, e, http.StatusOK, "m1", "PATCH", "/v1/members/"+bob.ID, e.Acme.Key, map[string]string{"role": "admin"}, nil)
	call(t, e, http.StatusNoContent, "m2", "DELETE", "/v1/members/"+bob.ID, e.Acme.Key, nil, nil)

	var ep store.WebhookEndpoint
	call(t, e, http.StatusCreated, "w1", "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	call(t, e, http.StatusOK, "w2", "PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/v2"}, nil)
	call(t, e, http.StatusNoContent, "w3", "DELETE", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil, nil)

	call(t, e, http.StatusOK, "o1", "PATCH", "/v1/org", e.Acme.Key, map[string]string{"name": "Acme Ltd"}, nil)

	// Oldest first, as the requests were made.
	wantActions := []string{
		"plan.created", "plan.updated",
		"customer.created", "customer.updated", "customer.created", "customer.deleted",
		"subscription.created", "subscription.updated", "subscription.canceled",
		"invoice.created", "invoice.voided", "invoice.created", "invoice.paid",
		"api_key.created", "api_key.revoked",
		"invite.created", "invite.revoked",
		"member.role_changed", "member.removed",
		"webhook_endpoint.created", "webhook_endpoint.updated", "webhook_endpoint.deleted",
		"org.updated",
	}
	log := auditLog(t, e, e.Acme.Key, "?limit=100")
	slices.Reverse(log)
	if len(log) != len(wantActions) {
		t.Fatalf("%d entries, want %d", len(log), len(wantActions))
	}
	seen := map[string]bool{}
	for i, ev := range log {
		if ev.Action != wantActions[i] {
			t.Fatalf("entry %d is %s, want %s", i, ev.Action, wantActions[i])
		}
		seen[ev.Action] = true
	}
	if len(seen) != 21 {
		t.Fatalf("%d different actions, want 21", len(seen))
	}

	byAction := map[string]auditEvent{}
	for _, ev := range log {
		byAction[ev.Action] = ev
	}
	if ev := byAction["subscription.canceled"]; ev.Target != (store.AuditTarget{Type: "subscription", ID: sub.ID}) || ev.Changes != nil {
		t.Fatalf("cancel = %+v", ev)
	}
	if ev := byAction["member.role_changed"]; ev.Target != (store.AuditTarget{Type: "member", ID: bob.ID}) || changed(t, ev)["role"].To != "admin" {
		t.Fatalf("role change = %+v", ev)
	}
	if got := changed(t, byAction["subscription.updated"]); len(got) != 1 || got["quantity"].From != float64(2) || got["quantity"].To != float64(3) {
		t.Fatalf("subscription update changed %+v", got)
	}
	if got := changed(t, byAction["org.updated"]); len(got) != 1 || got["name"].To != "Acme Ltd" {
		t.Fatalf("org update changed %+v", got)
	}
	if got := changed(t, byAction["webhook_endpoint.updated"]); len(got) != 1 || got["url"].To != "https://hooks.acme.example/v2" {
		t.Fatalf("endpoint update changed %+v", got)
	}

	// No secret appears in the log: not an API key token, a webhook secret or an invite token.
	body := e.Do("GET", "/v1/audit-events?limit=100", e.Acme.Key, nil).Body
	for _, secret := range []string{e.Acme.Key, ep.Secret, inv2.Token, key.Token} {
		if secret == "" || strings.Contains(string(body), secret) {
			t.Fatalf("the log shows the secret %q (or it is empty)", secret)
		}
	}
}

func TestAuditLogRecordsNothingElse(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": c.ID, "currency": "USD", "lines": []map[string]any{{"description": "x", "quantity": 1, "unit_amount": 100}}}, &inv)
	var invite store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@acme.example", "role": "member"}, &invite)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"*"}}, &ep)
	base := len(auditLog(t, e, e.Acme.Key, ""))

	// Requests that fail, or that another organization's object does not answer for.
	for _, f := range []struct {
		method, path, key string
		body              any
		code              int
	}{
		{"POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "", "email": "x@example.com"}, http.StatusUnprocessableEntity},
		{"POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "JANE@example.com"}, http.StatusConflict},
		{"PATCH", "/v1/org", member, map[string]string{"name": "Nope"}, http.StatusForbidden},
		{"POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": c.ID, "currency": "USD", "lines": []string{}}, http.StatusUnprocessableEntity},
		{"POST", "/v1/invoices/" + inv.ID + "/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_declined"}, http.StatusPaymentRequired},
		{"POST", "/v1/invoices/" + inv.ID + "/pay", e.Acme.Key, nil, http.StatusUnprocessableEntity},
		{"DELETE", "/v1/webhook-endpoints/" + ep.ID, e.Acme.Key, nil, http.StatusNotFound},
		{"PATCH", "/v1/customers/cus_999999", e.Acme.Key, map[string]string{"name": "Nobody"}, http.StatusNotFound},
	} {
		if r := e.Do(f.method, f.path, f.key, f.body); r.Code != f.code {
			t.Fatalf("%s %s: want %d, got %s", f.method, f.path, f.code, r)
		}
	}
	if n := len(auditLog(t, e, e.Acme.Key, "")); n != base {
		t.Fatalf("failed requests recorded %d entries", n-base)
	}
	if _, ok := e.Store.WebhookEndpoint(e.Globex.ID, ep.ID); !ok {
		t.Fatal("another organization's endpoint was deleted")
	}

	// Requests that succeed but are not of an audited kind.
	e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusCreated, "POST", "/v1/invites/accept", "", map[string]string{"token": invite.Token, "name": "New"}, nil)
	if n := len(auditLog(t, e, e.Acme.Key, "")); n != base {
		t.Fatalf("unaudited requests recorded %d entries", n-base)
	}
}

func TestAuditLogAccess(t *testing.T) {
	e := apitest.New(t)
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	_, billing := e.AddMember(e.Acme, "billing@acme.example", store.RoleBilling)
	_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	for _, key := range []string{billing, member, viewer} {
		r := e.Do("GET", "/v1/audit-events", key, nil)
		if r.Code != http.StatusForbidden || !reflect.DeepEqual(r.Map(t), map[string]any{"error": "forbidden"}) {
			t.Fatalf("%s", r)
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events", admin, nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events", e.Acme.Key, nil, nil)

	// Each organization sees only its own entries.
	gus := e.CreateCustomer(e.Globex, "Gus", "gus@globex.example")
	for _, ev := range auditLog(t, e, e.Acme.Key, "") {
		if ev.Target.ID == gus.ID {
			t.Fatal("Acme's log shows a change made at Globex")
		}
	}
	if got := auditLog(t, e, e.Globex.Key, ""); len(got) != 1 || got[0].Target.ID != gus.ID {
		t.Fatalf("Globex's log = %+v", got)
	}
}

