// auditEvent is an audit entry as GET /v1/audit-events shows it. Changes is nil when the entry has no changes field.
type auditEvent struct {
	ID        string                        `json:"id"`
	Action    string                        `json:"action"`
	Actor     store.AuditActor              `json:"actor"`
	Target    store.AuditTarget             `json:"target"`
	RequestID string                        `json:"request_id"`
