package store

import (
	"reflect"
	"testing"
	"time"
)

func TestAuditLog(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	actor := AuditActor{Type: "api_key", ID: "key_1", UserID: "usr_1"}
	changes := map[string]AuditChange{"name": {From: "Jane", To: "Joan"}}
	e1 := s.RecordAudit(AuditEntry{OrgID: a.ID, Action: "customer.created", Actor: actor, Target: AuditTarget{Type: "customer", ID: "cus_1"}, RequestID: "r1"}, t0)
	e2 := s.RecordAudit(AuditEntry{OrgID: a.ID, Action: "customer.updated", Actor: actor, Target: AuditTarget{Type: "customer", ID: "cus_1"}, RequestID: "r2", Changes: &changes}, t0.Add(time.Minute))
	s.RecordAudit(AuditEntry{OrgID: b.ID, Action: "plan.created", Actor: AuditActor{Type: "api_key", ID: "key_2", UserID: "usr_2"}, Target: AuditTarget{Type: "plan", ID: "pln_1"}}, t0)

	if e1.ID == e2.ID || e1.ID == "" || !e2.At.Equal(t0.Add(time.Minute)) {
		t.Fatalf("entries = %+v, %+v", e1, e2)
	}
	all := s.AuditEntries(a.ID, AuditFilter{})
	if !reflect.DeepEqual(all, []AuditEntry{e1, e2}) {
		t.Fatalf("A's entries, oldest first = %+v", all)
	}
	for _, tc := range []struct {
		f    AuditFilter
		want int
	}{
		{AuditFilter{Action: "customer.updated"}, 1},
		{AuditFilter{TargetID: "cus_1"}, 2},
		{AuditFilter{TargetID: "pln_1"}, 0},
		{AuditFilter{ActorID: "key_1"}, 2},
		{AuditFilter{ActorID: "usr_1"}, 2},
		{AuditFilter{ActorID: "key_2"}, 0},
	} {
		if got := s.AuditEntries(a.ID, tc.f); len(got) != tc.want {
			t.Fatalf("filter %+v: %d entries, want %d", tc.f, len(got), tc.want)
		}
	}
	if got := s.AuditEntries(b.ID, AuditFilter{}); len(got) != 1 || got[0].Action != "plan.created" {
		t.Fatalf("B's entries = %+v", got)
	}

	// The log survives an export, and its numbering goes on.
	s2, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got := s2.AuditEntries(a.ID, AuditFilter{}); !reflect.DeepEqual(got, all) {
		t.Fatalf("after FromState = %+v", got)
	}
	if e3 := s2.RecordAudit(AuditEntry{OrgID: a.ID, Action: "org.updated"}, t0); e3.ID == e1.ID || e3.ID == e2.ID {
		t.Fatalf("a restored log reused the ID %s", e3.ID)
	}

	// Audit entries have their own counter, so other objects keep their IDs.
	plain := New()
	pa := newOrg(t, plain, "A")
	want, _ := plain.CreateCustomer(pa.ID, "Jane", "jane@example.com", t0)
	audited := New()
	xa := newOrg(t, audited, "A")
	audited.RecordAudit(AuditEntry{OrgID: xa.ID, Action: "customer.created"}, t0)
	audited.RecordAudit(AuditEntry{OrgID: xa.ID, Action: "customer.created"}, t0)
	if got, _ := audited.CreateCustomer(xa.ID, "Jane", "jane@example.com", t0); got.ID != want.ID {
		t.Fatalf("customer ID %s, want %s", got.ID, want.ID)
	}
}

